arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        parts = []
        if self.spec is not T:
            parts.append('spec=%r' % (self.spec,))
        if self.type is not _MISSING:
            parts.append('type=%r' % (self.type,))
        if self.equal_to is not _MISSING:
            parts.append('equal_to=%r' % (self.equal_to,))
        if self.instance_of is not _MISSING:
            parts.append('instance_of=%r' % (self.instance_of,))
        if self.vals is not _MISSING and self.vals:
            parts.append('one_of=%r' % (self.vals,))
        if self.default is not RAISE:
            parts.append('default=%r' % (self.default,))
        return '%s(%s)' % (cn, ', '.join(parts)) if parts else '%s()' % cn


# =============================================================================
# New specifier types for data transformation
# =============================================================================

class Auto(object):
    """Auto objects enable automatic type-based dispatching in glom specs.

    Auto inspects the target type at runtime and applies different
    processing strategies based on what type it encounters. This enables
    streaming-like behavior where the same spec can handle different
    input types gracefully.

    Args:
       spec: The glom spec to apply when auto-detection succeeds
       default: A fallback value or spec if auto-detection fails

    >>> target = {'key': 'value'}
    >>> glom(target, Auto('key'))
    'value'

    """
    def __init__(self, spec=T, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except Exception:
            if self.default is not None:
                if callable(self.default) and hasattr(self.default, 'glomit'):
                    return scope[glom](target, self.default, scope)
                return self.default
            raise

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default is None:
            return '%s(%r)' % (cn, self.spec)
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Fill(object):
    """Fill objects fill in missing/None values with a default during glom processing.

    When the target matches the spec but produces None or is missing,
    Fill substitutes the provided *fill_value*.

    Args:
       spec: A glom spec to extract the value from the target
       fill_value: The value to use if the spec returns None or raises

    >>> target = {'a': None, 'b': 'exists'}
    >>> glom(target, Fill('a', 'default'))
    'default'
    >>> glom(target, Fill('b', 'default'))
    'exists'

    """
    def __init__(self, spec=T, fill_value=None):
        self.spec = spec
        self.fill_value = fill_value

    def glomit(self, target, scope):
        try:
            val = scope[glom](target, self.spec, scope)
            if val is None:
                return self.fill_value
            return val
        except Exception:
            return self.fill_value

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, fill_value=%r)' % (cn, self.spec, self.fill_value)


class Iter(object):
    """Iter objects iterate over iterables and transform each element.

    Similar to a list comprehension, Iter applies a subspec to each
    element of an iterable target.

    Args:
       subspec: A glom spec to apply to each item in the iterable

    >>> target = [1, 2, 3, 4]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6, 8]

    """
    def __init__(self, subspec):
        self.subspec = subspec

    def glomit(self, target, scope):
        try:
            iterator = iter(target)
        except TypeError as e:
            raise TypeError('Iter requires an iterable target, got %r' % (type(target).__name__,))
        result = []
        for i, item in enumerate(iterator):
            child_scope = scope.new_child({Path: scope[Path] + [i]})
            val = scope[glom](item, self.subspec, child_scope)
            if val is not SKIP:
                result.append(val)
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.subspec)


class Let(object):
    """Let objects bind variables within a scope for use by other specs.

    Let creates a temporary binding that other specs in the tuple can
    access via S (scope reference).

    Args:
       bindings: A dict mapping variable names to their values (specs)
       body: The main spec to execute with the bindings in scope

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'doubled_a': ('a', lambda x: x * 2)}, {'result': ('doubled_a', '+', 'b')}))
    Traceback (most recent call last):
    ...

    """
    def __init__(self, bindings, body):
        self.bindings = bindings
        self.body = body

    def glomit(self, target, scope):
        new_scope = scope.new_child()
        for name, spec in self.bindings.items():
            new_scope[name] = scope[glom](target, spec, scope)
        return scope[glom](target, self.body, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.bindings, self.body)


ROOT = make_sentinel('ROOT')
ROOT.__doc__ = """\
The ``ROOT`` sentinel object references the original root target from
within nested specs. This is useful when you need to access the
top-level data while operating on a sub-target.

>>> target = {'outer': {'inner': 'value'}}
>>> glom(target, ('outer', Fill(ROOT['original'], 'missing')))
'missing'
"""


class Invoke(object):
    """Invoke objects call/invoke an object with arguments extracted from the target.

    Invoke is similar to Call but designed for invoking callable targets
    directly, extracting arguments from the current target.

    Args:
       func: The callable to invoke (can be a spec to extract it from target)
       args: Positional arguments (can be specs to evaluate)
       kwargs: Keyword arguments (can be specs to evaluate)

    >>> def add(a, b):
    ...     return a + b
    >>> target = {'func': add, 'args': (1, 2)}
    >>> glom(target, Invoke('func', args=('args',)))
    3

    """
    def __init__(self, func, args=(), kwargs=None):
        self.func = func
        self.args = args if args else ()
        self.kwargs = kwargs if kwargs else {}

    def glomit(self, target, scope):
        def _eval(v):
            if isinstance(v, TType):
                return scope[glom](target, v, scope)
            elif isinstance(v, Spec):
                return scope[glom](target, v, scope)
            return v

        func_val = _eval(self.func)
        eval_args = tuple(_eval(a) for a in self.args)
        eval_kwargs = {k: _eval(v) for k, v in self.kwargs.items()}
        return func_val(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, args=%r, kwargs=%r)' % (cn, self.func, self.args, self.kwargs)


